1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over
7	 * the digits contained in the owner's {@code customerCode}. Non-digit characters are
8	 * ignored; the rightmost digit is doubled and doubling alternates leftward.
9	 */
10	public final class CheckDigits {
11	
12	    private CheckDigits() {
13	    }
14	
15	    /** The Luhn check digit (0-9) over the digits of the owner's customerCode. */
16	    public static int forOwner(Owner owner) {
17	        return luhn(owner.getCustomerCode());
18	    }
19	
20	    /** The Luhn check digit (0-9) over the digits contained in {@code value}. */
21	    public static int luhn(String value) {
22	        if (value == null) {
23	            return 0;
24	        }
25	        int sum = 0;
26	        boolean dbl = true;
27	        for (int i = value.length() - 1; i >= 0; i--) {
28	            char c = value.charAt(i);
29	            if (c < '0' || c > '9') {
30	                continue;
31	            }
32	            int d = c - '0';
33	            if (dbl) {
34	                d *= 2;
35	                if (d > 9) {
36	                    d -= 9;
37	                }
38	            }
39	            sum += d;
40	            dbl = !dbl;
41	        }
42	        return (10 - (sum % 10)) % 10;
43	    }
44	}
