1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Set;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.function.owner.CustomerCodes;
7	
8	/**
9	 * Derives an owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>}.
10	 *
11	 * <p>{@code TIER} is {@code PREMIUM} when the owner's {@link MembershipLevels#forOwner(Owner)
12	 * membershipLevel} is 3 or more, otherwise {@code STANDARD}. {@code AREA} is {@code METRO}
13	 * when the owner's {@link CustomerCodes#localityOf(Owner) locality} is a known region
14	 * (NSW, VIC or QLD), otherwise {@code REGIONAL}.
15	 */
16	public final class OwnerSegments {
17	
18	    /** Membership level at or above which an owner is in the PREMIUM tier. */
19	    private static final int PREMIUM_MIN_LEVEL = 3;
20	
21	    /** Localities that count as METRO; anything else is REGIONAL. */
22	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
23	
24	    private OwnerSegments() {
25	    }
26	
27	    /** The {@code <TIER>_<AREA>} segment for the given owner. */
28	    public static String forOwner(Owner owner) {
29	        String tier = MembershipLevels.forOwner(owner) >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
30	        String area = METRO_REGIONS.contains(CustomerCodes.localityOf(owner)) ? "METRO" : "REGIONAL";
31	        return tier + "_" + area;
32	    }
33	}
