1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where
12	 * REGION is the region code derived from the postcode and HASH8 is the first 8
13	 * upper-case hex characters of SHA-256 over (normalizedTelephone + lastName) — see
14	 * {@link CustomerCodes}. The base identity is a pure function of the owner's own fields.
15	 *
16	 * <p>When the computed code collides with an existing owner's {@code customerCode}, a
17	 * {@code -<n>} suffix is appended with the smallest {@code n} of 2 or more that makes it
18	 * unique, so distinct owners always end up with distinct customerCodes.
19	 */
20	public class AssignCustomerCode {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        Set<String> existing = new HashSet<>();
24	        for (Owner other : ownerRepository.findAll()) {
25	            if (other.getCustomerCode() != null) {
26	                existing.add(other.getCustomerCode());
27	            }
28	        }
29	        String base = CustomerCodes.forOwner(owner);
30	        String code = base;
31	        for (int n = 2; existing.contains(code); n++) {
32	            code = base + "-" + n;
33	        }
34	        owner.setCustomerCode(code);
35	    }
36	}
