1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * The one place that turns a string into its SHA-256 hex digest. Several owner
9	 * derivations are built on the same hash — {@link Households} (the {@code householdId}
10	 * prefix) and {@link CustomerCodes} (the {@code HASH8} segment) both fold their key
11	 * through it — so keeping the encoding here means every one of them agrees on the exact
12	 * bytes and hex form instead of each hand-rolling {@link MessageDigest}.
13	 *
14	 * <p>{@link #sha256Hex(String)} is the primitive: the full, lower-case hex string. Callers
15	 * that want a shorter, upper-case identifier take a {@code substring} and upper-case it, so
16	 * the slicing and casing stay a decision of the derivation, not of the hash.
17	 */
18	public final class Digests {
19	
20	    private Digests() {
21	    }
22	
23	    /** The full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
24	    public static String sha256Hex(String value) {
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256")
27	                    .digest(value.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder sb = new StringBuilder(digest.length * 2);
29	            for (byte b : digest) {
30	                sb.append(String.format("%02x", b));
31	            }
32	            return sb.toString();
33	        }
34	        catch (NoSuchAlgorithmException e) {
