4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.mapper.MembershipLevels;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.util.FiscalYears;
11	
12	import tools.jackson.databind.ObjectMapper;
13	import tools.jackson.databind.node.ObjectNode;
14	
15	/**
16	 * Emits an audit record for a freshly created owner via the dedicated {@code AUDIT}
17	 * logger. Runs after the owner is saved, so its generated id is populated. The line
18	 * carries the owner id, the assigned customerCode, the registrationDate, the
19	 * assigned membershipLevel and the membershipNumber.
20	 *
21	 * <p>Besides that human-readable line, it emits an immutable structured event as a
22	 * JSON object {@code {seq, ownerId, customerCode, membershipLevel, event}} with
23	 * {@code event = "OWNER_CREATED"}, where {@code seq} is a process-wide monotonically
24	 * increasing integer across creates. The event carries the owner's <em>current
25	 * primary identifier</em> ({@link #primaryIdentifier(Owner)}): the customerCode here,
26	 * and whatever replaces it later (e.g. a unified memberId).
27	 */
28	public class AuditOwnerCreated {
29	
30	    private static final Logger audit = LoggerFactory.getLogger("AUDIT");
31	
32	    private static final ObjectMapper JSON = new ObjectMapper();
33	
34	    /** Process-wide sequence, monotonically increasing across every create. */
35	    private static final AtomicLong SEQ = new AtomicLong(0);
36	
37	    public void service(@Val Owner owner) {
38	        String membershipNumber = owner.getCustomerCode() == null || owner.getRegistrationDate() == null
39	                ? null
40	                : owner.getCustomerCode() + "-M" + String.format("%02d", FiscalYears.yearSegment(owner.getRegistrationDate()));
41	        int membershipLevel = MembershipLevels.forOwner(owner);
42	        audit.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
43	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
44	                membershipLevel, membershipNumber);
45	
46	        ObjectNode event = JSON.createObjectNode();
47	        event.put("seq", SEQ.incrementAndGet());
48	        event.put("ownerId", owner.getId());
49	        event.put("customerCode", primaryIdentifier(owner));
50	        event.put("membershipLevel", membershipLevel);
51	        event.put("event", "OWNER_CREATED");
52	        audit.info(JSON.writeValueAsString(event));
53	    }
54	
55	    /**
56	     * The owner's current primary identifier. Today that is the customerCode; when the
57	     * customerCode is later unified into the memberId, change this single method so the
58	     * event carries the memberId instead.
59	     */
60	    private static String primaryIdentifier(Owner owner) {
61	        return owner.getCustomerCode();
62	    }
63	}
