1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Fiscal-year rules for owner date-derived values.
8	 *
9	 * <p>The fiscal year starts on 1 July, so a date in July–December falls in the fiscal
10	 * year that ends in the <em>following</em> calendar year. A fiscal year is identified by
11	 * the calendar year in which it ends and labelled {@code FY<YY>} (the last two digits of
12	 * that ending year); e.g. 1 July 2026 – 30 June 2027 is {@code FY27}.
13	 *
14	 * <p>Callers pass the business-day-adjusted registration date (an owner's stored
15	 * {@code registrationDate} is already adjusted by {@link BusinessDays}).
16	 */
17	public final class FiscalYears {
18	
19	    private FiscalYears() {
20	    }
21	
22	    /** The fiscal year (its ending calendar year) that {@code date} falls in. */
23	    public static int fiscalYear(LocalDate date) {
24	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
25	    }
26	
27	    /** The two-digit fiscal-year segment {@code <YY>} for {@code date} (0–99). */
28	    public static int yearSegment(LocalDate date) {
29	        return fiscalYear(date) % 100;
30	    }
31	
32	    /** The fiscal-year label {@code FY<YY>} for {@code date}. */
33	    public static String label(LocalDate date) {
34	        return String.format("FY%02d", yearSegment(date));
35	    }
36	}
