2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Rejects a create request that exactly duplicates an existing owner's identity. Identity is
11	 * the single {@link IdentityKeys#forFields(String, String, String) identity key} — the
12	 * SHA-256 of {@code normalizedTelephone + lowerEmail + soundex(lastName)} — so two owners
13	 * collide (409) only when all three components match. Two owners with the same last name and
14	 * postcode but different telephones no longer collide here: they are created and left for
15	 * {@link AssignPossibleDuplicate} to flag as a soft match. A 409 is reported by
16	 * {@link org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityExceptionHandler}.
17	 *
18	 * <p>The email-domain blocklist is applied earlier by {@link RequireOwnerFields} (a 400), so
19	 * a blocklisted request never reaches this check. Soft-deleted owners are ignored. Setting
20	 * {@code sharesHousehold} bypasses this block entirely: the owner is then created as a
21	 * declared household member (and, being declared, is not flagged as a possible duplicate).
22	 */
23	public class RequireUniqueIdentity {
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return; // a declared household member bypasses the duplicate block
29	        }
30	        String identityKey = IdentityKeys.forFields(request.getTelephone(), request.getEmail(),
31	                request.getLastName());
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (Boolean.TRUE.equals(existing.getDeleted())) {
34	                continue; // a soft-deleted owner does not block a new create
35	            }
36	            if (identityKey.equals(IdentityKeys.forOwner(existing))) {
37	                throw new DuplicateIdentityException(identityKey);
38	            }
39	        }
40	    }
41	}
