1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Computes an owner's {@code identityKey}: the SHA-256 hex digest over
7	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. It is the single
8	 * identity used for duplicate detection by {@link RequireUniqueIdentity} — two owners collide
9	 * (409) only when all three components match.
10	 *
11	 * <ul>
12	 * <li>telephone is normalized to E.164 form ({@link Telephones#toE164(String)}), contributing
13	 *     empty when it cannot form a valid number,
14	 * <li>email is trimmed and lower-cased, contributing empty when absent,
15	 * <li>lastName is folded to its {@link Soundex phonetic code}, so households that differ only
16	 *     by telephone or email produce different keys and are not hard duplicates.
17	 * </ul>
18	 */
19	public final class IdentityKeys {
20	
21	    private IdentityKeys() {
22	    }
23	
24	    /** The identity key of an existing owner, from its stored fields. */
25	    public static String forOwner(Owner owner) {
26	        return build(owner.getTelephone(), owner.getEmail(), owner.getLastName());
27	    }
28	
29	    /**
30	     * The identity key for an incoming create request, from its raw fields. Lets
31	     * {@link RequireUniqueIdentity} compare a request against existing owners'
32	     * {@link #forOwner(Owner) keys} without first building an entity.
33	     */
34	    public static String forFields(String telephone, String email, String lastName) {
35	        return build(telephone, email, lastName);
36	    }
37	
38	    private static String build(String telephone, String email, String lastName) {
39	        String tel = Telephones.toE164(telephone);
40	        String raw = (tel == null ? "" : tel) + "|" + normalizeEmail(email) + "|"
41	                + Soundex.encode(lastName);
42	        return Digests.sha256Hex(raw);
43	    }
44	
45	    /** Trim and lower-case; null or blank yields empty (no email to contribute). */
46	    private static String normalizeEmail(String email) {
47	        if (email == null || email.isBlank()) {
48	            return "";
49	        }
50	        return email.trim().toLowerCase();
51	    }
52	}
