3	import java.util.Locale;
4	
5	/**
6	 * Derives the stable {@code householdId} shared by owners with the same last name and
7	 * postcode. The id is the {@link #hash(String) SHA-256 prefix} of the normalized last name
8	 * and the postcode, so every owner in the same household (same normalized last name +
9	 * postcode) maps to the same value automatically — no opt-in is required.
10	 *
11	 * <p>Centralising the derivation here keeps {@link AssignHousehold} (which assigns the id)
12	 * and {@link IdentityKeys} (which folds it into an owner's identity key) in exact agreement.
13	 */
14	public final class Households {
15	
16	    private Households() {
17	    }
18	
19	    /** The stable {@code householdId} for the given last name and postcode. */
20	    public static String idFor(String lastName, String postcode) {
21	        return hash(normalize(lastName) + "|" + (postcode == null ? "" : postcode));
22	    }
23	
24	    /** Lower-case, trim, and collapse runs of whitespace to a single space. */
25	    public static String normalize(String value) {
26	        if (value == null) {
27	            return "";
28	        }
29	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
30	    }
31	
32	    /** Stable 12-hex-character (upper-case) prefix of the SHA-256 of the household key. */
33	    private static String hash(String value) {
34	        return Digests.sha256Hex(value).substring(0, 12).toUpperCase(Locale.ROOT);
35	    }
36	}
