2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality} (region) preferring the postcode over the city.
7	 *
8	 * <p>The region is resolved by postcode range first (NSW 2000-2099, VIC 3000-3099,
9	 * QLD 4000-4099); only when the postcode is absent or in no known range does it fall
10	 * back to a fixed city-to-region table. Anything unresolved maps to {@code UNKNOWN}.
11	 * This yields the same region for known cities but disambiguates cities that share a
12	 * name.
13	 */
14	public final class Localities {
15	
16	    private static final Map<String, String> CITY_REGION = Map.of(
17	        "Sydney", "NSW",
18	        "Melbourne", "VIC",
19	        "Brisbane", "QLD");
20	
21	    /** Region -> inclusive {low, high} 4-digit postcode range. */
22	    private static final Map<String, int[]> REGION_RANGE = Map.of(
23	        "NSW", new int[] {2000, 2099},
24	        "VIC", new int[] {3000, 3099},
25	        "QLD", new int[] {4000, 4099});
26	
27	    /** Region -> IANA timezone name. */
28	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
29	        "NSW", "Australia/Sydney",
30	        "VIC", "Australia/Melbourne",
31	        "QLD", "Australia/Brisbane");
32	
33	    private Localities() {
34	    }
35	
36	    /** The IANA timezone for the given region, or {@code null} when the region is unknown. */
37	    public static String timezoneForRegion(String region) {
38	        return REGION_TIMEZONE.get(region);
39	    }
40	
41	    /** The canonical region for the given city, or {@code UNKNOWN} when unlisted. */
42	    public static String forCity(String city) {
43	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
44	    }
45	
46	    /**
47	     * The region whose postcode range contains the given 4-digit postcode, or
48	     * {@code null} when the postcode is absent, malformed, or in no known range.
49	     */
50	    public static String forPostcode(String postcode) {
51	        if (postcode == null || postcode.isBlank()) {
52	            return null;
53	        }
54	        int value;
55	        try {
56	            value = Integer.parseInt(postcode.trim());
57	        }
58	        catch (NumberFormatException ex) {
59	            return null;
60	        }
61	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
62	            int[] range = entry.getValue();
63	            if (value >= range[0] && value <= range[1]) {
64	                return entry.getKey();
65	            }
66	        }
67	        return null;
68	    }
69	
70	    /**
71	     * The region for an owner, preferring the postcode range and falling back to the
72	     * city-to-region table when the postcode is absent or in no known range.
73	     */
74	    public static String forCityAndPostcode(String city, String postcode) {
75	        String byPostcode = forPostcode(postcode);
76	        return byPostcode != null ? byPostcode : forCity(city);
77	    }
78	}
