1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.util.FiscalYears;
7	
8	/**
9	 * Derives an owner's membership {@code points} and numeric {@code level}.
10	 *
11	 * <p>Points start at 0 and accumulate: add 2 when an email is present, add 1 when
12	 * {@code namesakeCount} is 0, add 2 for a household of 3 or more members, and add 3
13	 * for tenure over one fiscal year.
14	 *
15	 * <p>Points map to the level (1-4): 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for
16	 * 6 or more.
17	 */
18	public final class MembershipLevels {
19	
20	    /** Elapsed fiscal years above which an owner earns the tenure points. */
21	    private static final long TENURE_FISCAL_YEARS_FOR_BONUS = 1;
22	
23	    /** Household size at or above which an owner earns the household points. */
24	    private static final int HOUSEHOLD_SIZE_FOR_BONUS = 3;
25	
26	    private MembershipLevels() {
27	    }
28	
29	    /** The membership points for the given owner. */
30	    public static int pointsForOwner(Owner owner) {
31	        int points = 0;
32	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
33	            points += 2;
34	        }
35	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
36	            points += 1;
37	        }
38	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_SIZE_FOR_BONUS) {
39	            points += 2;
40	        }
41	        if (tenureInFiscalYears(owner) > TENURE_FISCAL_YEARS_FOR_BONUS) {
42	            points += 3;
43	        }
44	        return points;
45	    }
46	
47	    /**
48	     * The membership level (1-4) for the given owner, derived from its points and then
49	     * capped: when a {@code membershipLevelCap} is set (see
50	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevelCap}),
51	     * the level cannot exceed it. A {@code null} cap means no ceiling applies.
52	     */
53	    public static int forOwner(Owner owner) {
54	        int level = rawLevelForOwner(owner);
55	        Integer cap = owner.getMembershipLevelCap();
56	        return cap == null ? level : Math.min(level, cap);
57	    }
58	
59	    /** The uncapped membership level (1-4) for the given owner, derived from its points. */
60	    private static int rawLevelForOwner(Owner owner) {
61	        int points = pointsForOwner(owner);
62	        if (points <= 1) {
63	            return 1;
64	        }
65	        if (points <= 3) {
66	            return 2;
67	        }
68	        if (points <= 5) {
69	            return 3;
70	        }
71	        return 4;
72	    }
73	
74	    /**
75	     * Elapsed fiscal years since registration (the number of 1-July fiscal-year
76	     * boundaries crossed between the business-day-adjusted registration date and today),
77	     * or 0 when the registration date is unknown.
78	     */
79	    private static long tenureInFiscalYears(Owner owner) {
80	        LocalDate registrationDate = owner.getRegistrationDate();
81	        if (registrationDate == null) {
82	            return 0;
83	        }
84	        return FiscalYears.fiscalYear(LocalDate.now()) - FiscalYears.fiscalYear(registrationDate);
85	    }
86	}
